package com.intermarche.backoffice.engine.fieldops;
import com.intermarche.backoffice.domain.fieldops.*;
import com.intermarche.backoffice.domain.executing.*;
import com.intermarche.backoffice.domain.store.*;
import com.intermarche.backoffice.domain.shipping.*;
import com.intermarche.backoffice.domain.handling.HandlingExecution;
import com.intermarche.backoffice.client.PickingExecution;
import com.intermarche.backoffice.engine.operator.OperatorFailure;
import jakarta.enterprise.context.ApplicationScoped;import jakarta.inject.Inject;import jakarta.transaction.Transactional;import jakarta.ws.rs.*;import java.util.*;
import static com.intermarche.backoffice.domain.fieldops.FieldEntityIds.id;
@ApplicationScoped @Transactional
public class SupportStageService {
 private static final Set<Employee.EmployeeRole> RECIPIENT_ROLES=Set.of(Employee.EmployeeRole.ADMIN,Employee.EmployeeRole.MANAGER,Employee.EmployeeRole.PICKER);
 @Inject FieldOperationsService field;@Inject StockCommands receipts;@Inject ParcelService parcels;
 @org.eclipse.microprofile.openapi.annotations.media.Schema(name="SupportStageInput") public static class Input {public Long storeId,loadedToteId,parcelId,recipientId,id;public String requestKey,step,reason,expectedRevision;}
 record Cargo(String code,String snapshot,String initialOwner){}
 private Cargo cargo(Store s,Long toteId,Long parcelId){if((toteId==null)==(parcelId==null))throw new BadRequestException("Choisissez un seul support");
  if(parcelId!=null){Parcel p=Parcel.find("id=?1 and store=?2",parcelId,s).firstResult();if(p==null)throw new NotFoundException();parcels.requireLoadable(p);return new Cargo(p.code,field.hash(Arrays.asList(p.id,p.version,p.revisionNumber,p.state,p.closedSnapshot)),p.createdBy);}
  LoadedTote t=LoadedTote.findById(toteId);if(t==null||!Objects.equals(id(t.tote.store),s.id))throw new NotFoundException();if(t.buffer==null||t.items.isEmpty())throw new BadRequestException("Rangez le support rempli avant de le transmettre");var owners=new HashSet<String>();
  for(var e:PickingExecution.<PickingExecution>list("select distinct e from PickingExecution e join e.loadedTotes t where t.id=?1",t.id)){if(e.status!=HandlingExecution.ExecutionStatus.DONE)throw new OperatorFailure(409,"MISSION_NOT_FINISHED","Terminez la préparation avant de transmettre le support");owners.add(org.hibernate.Hibernate.unproxy(e.employee,Employee.class).badgeId);}
  if(owners.size()!=1)throw new BadRequestException("Responsable initial du support non identifié");var items=t.items.stream().sorted(Comparator.comparing(i->i.id)).toList();parcels.finalTrace(items);
  var data=new ArrayList<Object>();data.add(Arrays.asList(t.id,t.version,org.hibernate.Hibernate.unproxy(t.tote,Tote.class).version,t.tote.code,t.status,id(t.buffer),id(t.cabinet),t.cellRow,t.cellColumn));for(var i:items)data.add(Arrays.asList(i.id,i.version,i.quantity,i.status,id(i.product)));return new Cargo(t.tote.code,field.hash(data),owners.iterator().next());
 }
 private List<SupportStageTransfer> prior(Store s,Long tote,Long parcel){return SupportStageTransfer.list("store=?1 and "+(tote!=null?"loadedToteId":"parcelId")+"=?2 order by id desc",s,tote!=null?tote:parcel);}
 public Object offer(Input i){if(i==null)throw new BadRequestException();var s=field.store(i.storeId,true);var fp=field.hash(i);var old=receipts.previous(s,i.requestKey,fp);if(old!=null)return receipts.value(old);if(!Set.of("CONTROL","PACKING","CONSOLIDATION","SHIPPING").contains(i.step==null?"":i.step))throw new BadRequestException("Étape destinataire requise");FieldOperationsService.text(i.reason,500);Employee target=Employee.findById(i.recipientId);if(target==null||!target.active||!RECIPIENT_ROLES.contains(target.role)||!Objects.equals(id(target.store),s.id)||target.badgeId.equals(field.actor()))throw new BadRequestException("Choisissez un autre opérateur actif du magasin");var data=cargo(s,i.loadedToteId,i.parcelId);var previous=prior(s,i.loadedToteId,i.parcelId);if(previous.stream().anyMatch(t->"PENDING".equals(t.state)))throw new OperatorFailure(409,"TRANSFER_PENDING","Une transmission attend déjà son destinataire");var owner=previous.stream().filter(t->"ACCEPTED".equals(t.state)).findFirst().map(t->t.recipient).orElse(data.initialOwner);if(!owner.equals(field.actor()))throw new ForbiddenException("Seul le responsable actuel peut transmettre ce support");var t=new SupportStageTransfer();t.store=s;t.loadedToteId=i.loadedToteId;t.parcelId=i.parcelId;t.sender=field.actor();t.recipient=target.badgeId;t.step=i.step;t.reason=i.reason.trim();t.code=data.code;t.snapshot=data.snapshot;t.persistAndFlush();field.notice(s,"support-stage:"+t.id,"Support à prendre en charge",t.code+" · "+switch(t.step){case "CONTROL"->"Contrôle";case "PACKING"->"Emballage";case "CONSOLIDATION"->"Consolidation";default->"Expédition";},null,List.of(t.recipient));return receipts.record(s,i.requestKey,fp,"SUPPORT_STAGE_OFFER",view(t));}
 private String revision(SupportStageTransfer t){return field.hash(Arrays.asList(t.id,t.version,t.state,t.snapshot));}
 public Object decide(Input i,String action){if(i==null)throw new BadRequestException();var s=field.store(i.storeId,true);var fp=field.hash(Arrays.asList(action,i));var old=receipts.previous(s,i.requestKey,fp);if(old!=null)return receipts.value(old);SupportStageTransfer t=SupportStageTransfer.find("id=?1 and store=?2",i.id,s).firstResult();if(t==null)throw new NotFoundException();if(!Objects.equals(i.expectedRevision,revision(t))||!"PENDING".equals(t.state))throw new OperatorFailure(409,"STALE_SUPPORT_TRANSFER","La transmission a changé : actualisez");
  if("ACCEPT".equals(action)){if(!t.recipient.equals(field.actor()))throw new ForbiddenException("Seul le destinataire peut accepter");Employee receiver=Employee.findByBadgeId(t.recipient);if(receiver==null||!receiver.active||!RECIPIENT_ROLES.contains(receiver.role)||!Objects.equals(id(receiver.store),s.id))throw new ForbiddenException();var data=cargo(s,t.loadedToteId,t.parcelId);if(!data.snapshot.equals(t.snapshot))throw new OperatorFailure(409,"SUPPORT_CHANGED","Le support a changé : annulez puis préparez une nouvelle transmission");t.state="ACCEPTED";t.acceptedAt=com.intermarche.backoffice.domain.util.DateTimeProvider.now();}
  else if("CANCEL".equals(action)){if(!t.sender.equals(field.actor())&&!t.recipient.equals(field.actor()))throw new ForbiddenException();FieldOperationsService.text(i.reason,500);t.state="CANCELLED";t.reason=i.reason.trim();}else throw new BadRequestException();t.persistAndFlush();field.notice(s,"support-stage-decision:"+t.id+":"+t.state,"Transmission du support",t.code+" · "+("ACCEPTED".equals(t.state)?"Pris en charge":"Transmission annulée"),null,List.of(t.sender,t.recipient));return receipts.record(s,i.requestKey,fp,"SUPPORT_STAGE_"+action,view(t));
 }
 public Object recipients(Long storeId){var store=field.store(storeId,false);return Employee.<Employee>list("store=?1 and active=true and role in ?2 order by lastName,firstName",store,RECIPIENT_ROLES).stream().filter(e->!field.actor().equals(e.badgeId)).map(e->Map.of("id",e.id,"name",e.getFullName(),"badge",e.badgeId)).toList();}
 public Object list(Long storeId,long before){var s=field.store(storeId,false);String actor=field.actor();var rows=SupportStageTransfer.<SupportStageTransfer>find("store=?1 and (sender=?2 or recipient=?2) and (?3=0 or id<?3) order by id desc",s,actor,before).range(0,30).list();return Map.of("items",rows.stream().limit(30).map(this::view).toList(),"hasMore",rows.size()>30,"nextBefore",rows.isEmpty()?0:rows.get(Math.min(29,rows.size()-1)).id);}
 private Map<String,Object> view(SupportStageTransfer t){var v=new LinkedHashMap<String,Object>();v.put("id",t.id);v.put("loadedToteId",t.loadedToteId);v.put("parcelId",t.parcelId);v.put("code",t.code);v.put("step",t.step);v.put("state",t.state);v.put("sender",t.sender);v.put("recipient",t.recipient);var sender=Employee.findByBadgeId(t.sender);var receiver=Employee.findByBadgeId(t.recipient);v.put("senderName",sender==null?t.sender:sender.getFullName());v.put("recipientName",receiver==null?t.recipient:receiver.getFullName());String kind="TOTE";if(t.parcelId!=null){Parcel p=Parcel.findById(t.parcelId);if(p!=null)kind=p.packagingType;}else{LoadedTote load=LoadedTote.findById(t.loadedToteId);PhysicalSupport physical=load==null?null:PhysicalSupport.find("tote",load.tote).firstResult();if(physical!=null)kind=physical.type.kind.name();}v.put("kind",kind);v.put("recipientMine",t.recipient.equals(field.actor()));v.put("senderMine",t.sender.equals(field.actor()));v.put("responsible",t.state.equals("ACCEPTED")?t.recipient:t.sender);v.put("acceptedAt",t.acceptedAt);v.put("reason",t.reason);v.put("revision",revision(t));return v;}
}
